#include <stdio.h>

/* Returns 1 if byte b is a whitespace character (as defined by the spec). */
static int is_ws(unsigned char b)
{
    return b == ' ' || b == '\t' || b == '\n' || b == '\v' ||
           b == '\f' || b == '\r';
}

int main(void)
{
    long lines = 0;      /* number of \n bytes */
    long words = 0;      /* maximal runs of non-whitespace */
    long bytes = 0;
    long maxlen = 0;     /* length of longest line (not counting \n) */

    int in_word = 0;     /* are we currently inside a word for this line? */
    long cur_line_len = 0; /* current line's length in bytes (not counting \n) */

    /* Read byte-by-byte to handle any input without buffering constraints.
       Using getchar in binary-compatible mode; reading single chars avoids
       getline/malloc concerns. */

#ifdef _WIN32
    /* On Windows, ensure stdin is in binary mode so we count bytes exactly. */
    _setmode(_fileno(stdin), _O_BINARY);
#endif

    while (1) {
        int ch = getchar();
        if (ch == EOF)
            break;

        unsigned char c = (unsigned char)ch;

        bytes++;

        if (c == '\n') {
            lines++;
            /* Update maxlen with the current line length before resetting. */
            if (cur_line_len > maxlen)
                maxlen = cur_line_len;
            cur_line_len = 0;
            in_word = 0;   /* a \n ends any word regardless */
        } else {
            cur_line_len++;

            if (is_ws(c)) {
                /* Whitespace byte — not part of a line length for maxlen purposes?
                   Wait: maxlen counts every byte except the final \n.
                   So \r, \t, etc. all count as bytes within the line. */
                in_word = 0;   /* whitespace can't be inside a non-ws run */
            } else {
                /* Non-whitespace byte */
                if (!in_word) {
                    words++;
                    in_word = 1;
                }
            }
        }
    }

    /* Handle the case where input does not end with a newline.
       The final "line" without \n still counts as a line, so lines++ only if
       we had non-whitespace or the file is non-empty and didn't end with \n. */

    /* Check: did we have a partial line (non-terminated by \n)? */
    if (cur_line_len > 0 || bytes == 0) {
        /* If input is completely empty (bytes == 0 output nothing? No —
           even empty input has max of zeros). Wait: if there's trailing
           content not followed by \n, we count that as a line already.

           Actually re-read: "A last line without a trailing newline counts 
           as a line for this value" (for maxlen). But lines counts \n bytes,
           so if the file doesn't end with \n, the final partial line does NOT
           increment `lines`. We only track that for maxlen. */

        /* For maxlen: yes, we still update with cur_line_len */
        if (cur_line_len > 0) {
            if (cur_line_len > maxlen)
                maxlen = cur_line_len;
        }
    }

    printf("%ld %ld %ld %ld\n", lines, words, bytes, maxlen);

    return 0;
}

